effect.shader:
void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    float maxC = max(color.r, max(color.g, color.b));
    float minC = min(color.r, min(color.g, color.b));
    float currentSaturation = maxC - minC;

    float luma = dot(color.rgb, vec3(0.299, 0.587, 0.114));

    // Quanto mais saturado já está, menos recebe. É a definição de vibração.
    float weight = (1.0 - currentSaturation) * vibranceF;

    // Tons de pele ficam em torno do laranja. Sem esta proteção, aumentar a
    // vibração de um retrato deixa a pessoa cor de tijolo — e é a reclamação
    // número um de quem usa saturação sem pensar.
    if (skinProtect > 0.0 && color.r > color.g && color.g > color.b) {
        float skinness = clamp((color.r - color.b) * 2.0, 0.0, 1.0);
        weight *= 1.0 - skinness * skinProtect;
    }

    vec3 result = mix(vec3(luma), color.rgb, 1.0 + weight);
    result = mix(vec3(dot(result, vec3(0.299, 0.587, 0.114))), result, 1.0 + saturationF);

    fragColor = vec4(clamp(result, 0.0, 1.0), color.a);
}
